# Generates rust/ged/src/storage/marcel_tables.rs from the Marcel gem that
# Active Storage uses to identify uploads (`Marcel::MimeType.for io,
# name:, declared_type:`), so the Rust detector runs the *same* tables:
# Marcel's EXTENSIONS, TYPE_PARENTS and MAGIC after the app's definitions.rb
# overrides, in Marcel's own priority order.
#
# The marcel gem and config/initializers live only on the local tag
# rails-final. Check that tag out in another worktree, then run:
#
#   bundle exec ruby rust/ged/tests/fixtures/gen_marcel_tables.rb
require "marcel"

OUT = File.expand_path("../../src/storage/marcel_tables.rs", __dir__)

def bytes(str) = "b\"" + str.b.bytes.map { |b| format("\\x%02x", b) }.join + "\""
def s(str) = str.inspect

def match(entry)
  offset, value, children = entry
  start, stop = offset.is_a?(Range) ? [offset.begin, offset.end] : [offset, nil]
  raise "exclusive range" if offset.is_a?(Range) && offset.exclude_end?
  v = case value
      when nil then "Value::Never"
      when Regexp
        raise "regexp options" unless value.options.zero?
        "Value::Regex(#{s(value.source)})"
      else "Value::Bytes(#{bytes(value)})"
      end
  kids = children ? "&[#{children.map { |c| match(c) }.join(", ")}]" : "&[]"
  "Match { start: #{start}, end: #{stop ? "Some(#{stop})" : "None"}, value: #{v}, children: #{kids} }"
end

max = 0
walk = lambda do |ms|
  ms.each do |o, v, ch|
    len = v.nil? ? 0 : (v.is_a?(Regexp) ? 256 : v.bytesize)
    max = [max, (o.is_a?(Range) ? o.end : o) + len].max
    walk.(ch) if ch
  end
end
Marcel::MAGIC.each { |_, m| walk.(m) }

ext = Marcel::EXTENSIONS.sort.map { |k, v| "    (#{s(k)}, #{s(v)})," }
parents = Marcel::TYPE_PARENTS.sort.map { |k, v| "    (#{s(k)}, &[#{v.map { |p| s(p) }.join(", ")}])," }
magic = Marcel::MAGIC.map { |type, ms| "    (#{s(type)}, &[#{ms.map { |m| match(m) }.join(", ")}])," }

File.write(OUT, <<~RS)
  // @generated by tests/fixtures/gen_marcel_tables.rb from marcel #{Marcel::VERSION}. Do not edit.
  #![allow(clippy::all)]

  use super::content_type::{Match, Value};

  /// Largest byte offset any magic rule reads (so a prefix this long is enough).
  pub const MAX_READ: usize = #{max};

  /// extension (lowercase, no dot) -> type; sorted for binary search.
  pub static EXTENSIONS: &[(&str, &str)] = &[
  #{ext.join("\n")}
  ];

  /// type -> parent types; sorted for binary search.
  pub static PARENTS: &[(&str, &[&str])] = &[
  #{parents.join("\n")}
  ];

  /// Magic rules in Marcel's priority order (first match wins).
  pub static MAGIC: &[(&str, &[Match])] = &[
  #{magic.join("\n")}
  ];
RS
puts "wrote #{OUT} (#{File.size(OUT)} bytes, marcel #{Marcel::VERSION})"
